  const b = $json.body || {};
  const escapeHtml = (value) => String(value);
  const lines = [];

  lines.push('🔔 ' + escapeHtml(b.formulario || 'Novo Lead Comercial') + '');
  lines.push('');

  const name = b.name || b.nome;
  if (name) lines.push('👤 Nome: ' + escapeHtml(name));

