  if (empresa) lines.push('🏢 Empresa: ' + escapeHtml(empresa));

  if (b.email) lines.push('📧 E-mail: ' + escapeHtml(b.email));

  const rawPhone = b.phone || b.whatsapp;
  if (rawPhone) {
    const digits = String(rawPhone).replace(/\D/g, '');
    const cleanPhone = digits.length > 0 ? (digits.length <= 11 ? '55' + digits : digits) : '';
    const waLink = cleanPhone ? 'https://wa.me/' + cleanPhone : escapeHtml(rawPhone);
    lines.push('📱 WhatsApp: ' + waLink);
  }

  if (b.necessidade) lines.push('🎯 Necessidade: ' + escapeHtml(b.necessidade));

  const segmento = b.segment || b.segmento;
  if (segmento) lines.push('🍕 Segmento: ' + escapeHtml(segmento));

  if (b.city || b.state) {
    const loc = [b.city, b.state].filter(Boolean).join(' - ');
    if (loc) lines.push('📍 Localização: ' + escapeHtml(loc));
  }

  if (b.locations && Number(b.locations) > 1) lines.push('🏪 Unidades: ' + escapeHtml(b.locations));

  if (b.monthlyDeliveryOrders && b.monthlyDeliveryOrders !== 'N/A') lines.push('📦 Pedidos/Mês: ' + escapeHtml(b.monthlyDeliveryOrders));

  if (b.platforms) {
    const platStr = Array.isArray(b.platforms) ? b.platforms.join(', ') : b.platforms;
    if (platStr && platStr !== 'N/A') lines.push('🛵 Plataformas: ' + escapeHtml(platStr));
  }

  if (b.preferredContact && b.preferredContact !== 'whatsapp') lines.push('💬 Contato Preferencial: ' + escapeHtml(b.preferredContact));

  const msg = b.currentPain || b.mensagem;
  if (msg && msg !== 'N/A') lines.push('📝 Mensagem: ' + escapeHtml(msg));

  if (b.origem) lines.push('🌐 Origem: ' + escapeHtml(b.origem));

  if (b.id && b.id !== 'N/A') lines.push('🆔 ID: ' + escapeHtml(b.id) + '');

  return lines.join('\n');
